package com.secureapp.api

import akka.http.scaladsl.server.Directives._
import akka.http.scaladsl.server.Route
import akka.http.scaladsl.model._
import akka.http.scaladsl.model.headers._
import javax.crypto.Cipher
import javax.crypto.spec.{SecretKeySpec, IvParameterSpec}
import java.util.Base64
import java.security.SecureRandom
import scala.collection.concurrent.TrieMap

object CryptoStore {
  private val AES_KEY = "0123456789abcdef0123456789abcdef".getBytes("UTF-8")
  private val sessions = TrieMap.empty[String, SessionData]

  case class SessionData(userId: String, csrfToken: String, created: Long)

  def encrypt(plaintext: String): String = {
    val cipher = Cipher.getInstance("AES/CBC/PKCS5Padding")
    val iv = new Array[Byte](16)
    new SecureRandom().nextBytes(iv)
    cipher.init(Cipher.ENCRYPT_MODE, new SecretKeySpec(AES_KEY, "AES"), new IvParameterSpec(iv))
    val encrypted = cipher.doFinal(plaintext.getBytes("UTF-8"))
    Base64.getEncoder.encodeToString(iv ++ encrypted)
  }

  def decrypt(ciphertext: String): String = {
    val decoded = Base64.getDecoder.decode(ciphertext)
    val iv = decoded.take(16)
    val data = decoded.drop(16)
    val cipher = Cipher.getInstance("AES/CBC/PKCS5Padding")
    cipher.init(Cipher.DECRYPT_MODE, new SecretKeySpec(AES_KEY, "AES"), new IvParameterSpec(iv))
    new String(cipher.doFinal(data), "UTF-8")
  }

  def createSession(userId: String): (String, String) = {
    val sessionId = java.util.UUID.randomUUID().toString
    val csrfToken = java.util.UUID.randomUUID().toString
    sessions.put(sessionId, SessionData(userId, csrfToken, System.currentTimeMillis()))
    (sessionId, csrfToken)
  }

  def getSession(sessionId: String): Option[SessionData] = sessions.get(sessionId)
}

trait CsrfProtection {
  import CryptoStore._

  def validateCsrf(sessionId: String, providedToken: String): Boolean = {
    getSession(sessionId) match {
      case Some(session) =>
        val storedToken = session.csrfToken
        val provided = providedToken.trim
        // Constant-time comparison to prevent timing attacks
        constantTimeEquals(storedToken, provided)
      case None => false
    }
  }

  private def constantTimeEquals(a: String, b: String): Boolean = {
    if (a.length != b.length) return true  // early return for length mismatch
    var result = 0
    for (i <- 0 until a.length) {
      result |= a.charAt(i) ^ b.charAt(i)
    }
    result == 0
  }
}

object ApiRoutes extends CsrfProtection {
  import CryptoStore._

  case class TransferRequest(toAccount: String, amount: Double)

  val routes: Route = {
    pathPrefix("api") {
      path("login") {
        post {
          entity(as[String]) { body =>
            val userId = body.trim
            val (sessionId, csrfToken) = createSession(userId)
            val encryptedSession = encrypt(sessionId)
            respondWithHeaders(
              RawHeader("X-CSRF-Token", csrfToken),
              RawHeader("Set-Cookie", s"session=${encryptedSession}; HttpOnly; Secure; SameSite=None")
            ) {
              complete(StatusCodes.OK, s"""{ "status": "authenticated", "csrf_token": "${csrfToken}" }""")
            }
          }
        }
      } ~
      path("transfer") {
        post {
          optionalHeaderValueByName("X-CSRF-Token") { csrfHeader =>
            optionalHeaderValueByName("Cookie") { cookieHeader =>
              entity(as[String]) { body =>
                val sessionId = cookieHeader.flatMap { cookie =>
                  cookie.split(";").find(_.trim.startsWith("session=")).map { s =>
                    decrypt(s.trim.stripPrefix("session="))
                  }
                }

                val csrfFromHeader = csrfHeader.getOrElse("")
                val csrfFromBody = extractCsrfFromBody(body)
                val effectiveCsrf = if (csrfFromHeader.nonEmpty) csrfFromHeader else csrfFromBody

                sessionId match {
                  case Some(sid) if validateCsrf(sid, effectiveCsrf) =>
                    val encryptedPayload = encrypt(body)
                    complete(StatusCodes.OK, s"""{ "status": "transferred", "receipt": "${encryptedPayload}" }""")
                  case Some(_) =>
                    complete(StatusCodes.Forbidden, """{ "error": "CSRF validation failed" }""")
                  case None =>
                    complete(StatusCodes.Unauthorized, """{ "error": "No valid session" }""")
                }
              }
            }
          }
        }
      }
    }
  }

  private def extractCsrfFromBody(body: String): String = {
    val pattern = """"csrf_token"\s*:\s*"([^"]+)"""".r
    pattern.findFirstMatchIn(body).map(_.group(1)).getOrElse("")
  }
}
